// Helper: check if a CallExpr calls roundup_pow_of_two(...)
bool SAGenTestChecker::isRoundupPow2Call(const CallExpr *CE, CheckerContext &C) {
  if (!CE)
    return false;

  // The kernel macro roundup_pow_of_two(n) expands to a conditional over
  // __builtin_constant_p(n), ilog2(...) and __roundup_pow_of_two(n), so accept
  // the implementation function as part of the same API contract.
  if (const FunctionDecl *FD = CE->getDirectCallee()) {
    if (FD->getIdentifier() &&
        (FD->getName() == "roundup_pow_of_two" ||
         FD->getName() == "__roundup_pow_of_two"))
      return true;
  }
  // Source-text check; containment also matches __roundup_pow_of_two(...).
  if (ExprHasName(CE, "roundup_pow_of_two", C))
    return true;
  if (CE->getCallee() && ExprHasName(CE->getCallee(), "roundup_pow_of_two", C))
    return true;

  return false;
}

// Helper: determine if expression equals integer zero (or null constant)
bool SAGenTestChecker::isZeroConstant(const Expr *E, CheckerContext &C) {
  if (!E)
    return false;

  llvm::APSInt Res;
  if (EvaluateExprToInt(Res, E, C))
    return Res == 0;

  if (const auto *IL = dyn_cast<IntegerLiteral>(E->IgnoreParenCasts()))
    return IL->getValue() == 0;

  // Also consider NULL-like constants
  if (E->isNullPointerConstant(C.getASTContext(), Expr::NPC_ValueDependentIsNull))
    return true;

  return false;
}

// Helper: from a condition, extract the expression that is being checked for zero
// Match: !X  -> ECheck = X
//        X == 0 or 0 == X -> ECheck = X
bool SAGenTestChecker::extractCheckedExpr(const Expr *Cond, const Expr* &ECheck, CheckerContext &C) {
  if (!Cond)
    return false;

  const Expr *ECond = Cond->IgnoreParenImpCasts();

  if (const auto *UO = dyn_cast<UnaryOperator>(ECond)) {
    if (UO->getOpcode() == UO_LNot) {
      ECheck = UO->getSubExpr();
      return true;
    }
  }

  if (const auto *BO = dyn_cast<BinaryOperator>(ECond)) {
    if (BO->getOpcode() == BO_EQ) {
      const Expr *L = BO->getLHS();
      const Expr *R = BO->getRHS();
      if (isZeroConstant(L, C)) {
        ECheck = R;
        return true;
      }
      if (isZeroConstant(R, C)) {
        ECheck = L;
        return true;
      }
    }
  }

  return false;
}

// Report a concise warning
void SAGenTestChecker::reportIssue(const Stmt *CondSite, const Stmt *OriginCE, CheckerContext &C) const {
  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(
      *BT,
      "Unreliable overflow check after roundup_pow_of_two()",
      N);

  if (CondSite)
    R->addRange(CondSite->getSourceRange());

  if (OriginCE) {
    PathDiagnosticLocation Loc =
        PathDiagnosticLocation::createBegin(OriginCE, C.getSourceManager(), C.getLocationContext());
    R->addNote("Value comes from roundup_pow_of_two() here", Loc);
  }

  if (CondSite) {
    PathDiagnosticLocation Loc2 =
        PathDiagnosticLocation::createBegin(CondSite, C.getSourceManager(), C.getLocationContext());
    R->addNote("roundup_pow_of_two() may overflow (UB) on 32-bit; check the input before rounding (e.g., x > 1UL << 31).", Loc2);
  }

  C.emitReport(std::move(R));
}

// Return the value expression stored at a bind site: the RHS of an
// assignment or a variable initializer.
const Expr *SAGenTestChecker::getBoundValueExpr(const Stmt *S) {
  if (!S)
    return nullptr;
  if (const auto *BO = dyn_cast<BinaryOperator>(S)) {
    if (BO->isAssignmentOp())
      return BO->getRHS();
    return nullptr;
  }
  if (const auto *DS = dyn_cast<DeclStmt>(S)) {
    const auto *VD = dyn_cast_or_null<VarDecl>(DS->getSingleDecl());
    if (!VD)
      return nullptr;
    return VD->getInit();
  }
  return dyn_cast<Expr>(S);
}

// Search a statement for a call belonging to the roundup_pow_of_two API.
bool SAGenTestChecker::findRoundupCall(const Stmt *S, CheckerContext &C, const CallExpr **Found) {
  if (!S)
    return false;
  if (const auto *CE = dyn_cast<CallExpr>(S)) {
    if (isRoundupPow2Call(CE, C)) {
      if (Found)
        *Found = CE;
      return true;
    }
  }
  for (const Stmt *Child : S->children()) {
    if (findRoundupCall(Child, C, Found))
      return true;
  }
  return false;
}

// The macro substitutes its single argument everywhere in the expansion, so
// the matched call's first argument (or, failing that, the argument of the
// first one-parameter call in the expansion) is the helper input.
const Expr *SAGenTestChecker::getRoundupArgExpr(const Expr *RHS, const CallExpr *Found) {
  if (Found && Found->getNumArgs() >= 1)
    return Found->getArg(0)->IgnoreParenImpCasts();
  const CallExpr *First = findSpecificTypeInChildren<CallExpr>(RHS);
  if (First && First->getNumArgs() == 1)
    return First->getArg(0)->IgnoreParenImpCasts();
  return nullptr;
}

// Stable region key for the memory location an expression denotes: the field
// region rooted at the base's value region for member accesses, the variable
// region otherwise. This matches the regions the engine itself computes.
const MemRegion *SAGenTestChecker::getValueKeyRegion(const Expr *E, CheckerContext &C, ProgramStateRef State) {
  if (!E)
    return nullptr;
  E = E->IgnoreParenImpCasts();
  if (const auto *ME = dyn_cast<MemberExpr>(E)) {
    const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl());
    if (!FD)
      return nullptr;
    SVal BaseV = State->getSVal(ME->getBase(), C.getLocationContext());
    if (!BaseV.getAsRegion())
      return nullptr;
    Loc FieldL = State->getLValue(FD, BaseV);
    return FieldL.getAsRegion();
  }
  if (const auto *DRE = dyn_cast<DeclRefExpr>(E)) {
    const auto *VD = dyn_cast<VarDecl>(DRE->getDecl());
    if (!VD)
      return nullptr;
    Loc VarL = State->getLValue(VD, C.getLocationContext());
    return VarL.getAsRegion();
  }
  return nullptr;
}

// Silence condition: a dominating early-exit guard already bounds this input
// region to at most 1UL << 31, exactly the relation the fixed revision
// establishes before calling roundup_pow_of_two().
bool SAGenTestChecker::isGuardedRoundupInput(const Expr *ArgE, CheckerContext &C, ProgramStateRef State) {
  const MemRegion *Key = getValueKeyRegion(ArgE, C, State);
  if (!Key)
    return false;
  const unsigned *Bounded = State->get<InputBoundMap>(Key);
  return Bounded && *Bounded != 0;
}

// Capacity/value relation: roundup_pow_of_two(n) computes 1UL << (ilog2(n - 1) + 1),
// which is undefined on a 32-bit target once n > 1UL << 31.
bool SAGenTestChecker::inputCanExceedRoundupLimit(const Expr *ArgE, CheckerContext &C) {
  llvm::APSInt ArgV;
  if (EvaluateExprToInt(ArgV, ArgE, C)) {
    if (ArgV.isNegative())
      return true;
    return ArgV.ugt(2147483648ULL);
  }

  ASTContext &ACtx = C.getASTContext();
  QualType T = ArgE->getType();
  if (!T->isIntegralOrEnumerationType())
    return false;
  uint64_t Width = ACtx.getTypeSize(T);
  if (T->isUnsignedIntegerOrEnumerationType())
    return Width > 31;
  return Width > 32;
}

// Record the patch's guard: an if() whose condition bounds a value region by
// the overflow limit and whose true branch exits the path (barrier), so every
// following statement on this path sees an input <= 1UL << 31.
bool SAGenTestChecker::recordInputBound(const Expr *CondE, CheckerContext &C) {
  ASTContext &ACtx = C.getASTContext();
  const Expr *E = CondE->IgnoreParenImpCasts();
  const auto *BO = dyn_cast<BinaryOperator>(E);
  if (!BO)
    return false;

  const Expr *CheckedE = nullptr;
  const Expr *LimitE = nullptr;
  bool Strict = false;
  switch (BO->getOpcode()) {
  case BO_GT:
    CheckedE = BO->getLHS();
    LimitE = BO->getRHS();
    Strict = true;
    break;
  case BO_GE:
    CheckedE = BO->getLHS();
    LimitE = BO->getRHS();
    break;
  case BO_LT:
    CheckedE = BO->getRHS();
    LimitE = BO->getLHS();
    Strict = true;
    break;
  case BO_LE:
    CheckedE = BO->getRHS();
    LimitE = BO->getLHS();
    break;
  default:
    return false;
  }

  llvm::APSInt LimitV;
  if (!EvaluateExprToInt(LimitV, LimitE, C))
    return false;
  if (LimitV.isNegative() || LimitV.getBitWidth() > 64)
    return false;
  // The bound must cap the value at the overflow threshold n <= 1UL << 31.
  uint64_t Allowed = Strict ? 2147483648ULL : 2147483649ULL;
  if (LimitV.getZExtValue() > Allowed)
    return false;

  // The bound only helps when the true branch leaves the path.
  const IfStmt *OwnerIS = nullptr;
  for (const auto &P : ACtx.getParents(*CondE)) {
    if (const auto *I = P.get<IfStmt>()) {
      OwnerIS = I;
      break;
    }
  }
  if (!OwnerIS)
    return false;
  if (OwnerIS->getCond()->IgnoreParenImpCasts() != E)
    return false;
  if (!stmtContainsEarlyExit(OwnerIS->getThen()))
    return false;

  ProgramStateRef State = C.getState();
  const MemRegion *Key = getValueKeyRegion(CheckedE, C, State);
  if (!Key)
    return false;
  State = State->set<InputBoundMap>(Key, 1u);
  C.addTransition(State);
  return true;
}

bool SAGenTestChecker::stmtContainsEarlyExit(const Stmt *S) {
  if (!S)
    return false;
  if (isa<ReturnStmt>(S) || isa<GotoStmt>(S))
    return true;
  for (const Stmt *Child : S->children()) {
    if (stmtContainsEarlyExit(Child))
      return true;
  }
  return false;
}

// Track binds. A bind whose value comes from roundup_pow_of_two(...) is the
// trigger: on a 32-bit target the helper shifts 1UL by ilog2(n - 1) + 1 and
// overflows once the, so far unbounded, input can exceed 1UL << 31. When the
// same input region was bounded by a dominating early-exit guard (the fixed
// revision's relation), stay silent.
void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const {
  const MemRegion *LReg = Loc.getAsRegion();
  if (!LReg)
    return;
  LReg = LReg->getBaseRegion();
  if (!LReg)
    return;

  // Only the 32-bit unsigned long target has the shift-overflow relation.
  ASTContext &ACtx = C.getASTContext();
  if (ACtx.getTypeSize(ACtx.UnsignedLongTy) != 32)
    return;

  ProgramStateRef State = C.getState();

  // Storing to a region invalidates a previously recorded bound on it, and
  // stale roundup tracking for this region is cleared as well.
  if (const MemRegion *FullR = Loc.getAsRegion())
    State = State->remove<InputBoundMap>(FullR);
  State = State->remove<InputBoundMap>(LReg);
  State = State->remove<RoundupResMap>(LReg);

  const Expr *RHS = getBoundValueExpr(S);
  const CallExpr *Found = nullptr;
  bool IsRoundup = RHS && (findRoundupCall(RHS, C, &Found) ||
                           ExprHasName(RHS, "roundup_pow_of_two", C));
  if (!IsRoundup) {
    C.addTransition(State);
    return;
  }

  const Expr *ArgE = getRoundupArgExpr(RHS, Found);

  // Fixed-side silence: the input region is already bounded <= 1UL << 31.
  if (ArgE && isGuardedRoundupInput(ArgE, C, State)) {
    C.addTransition(State);
    return;
  }

  C.addTransition(State);

  // Vulnerable-side trigger: unbounded input able to exceed the limit.
  if (!ArgE || inputCanExceedRoundupLimit(ArgE, C))
    reportIssue(S, Found, C);
}

// Detect conditions like !n or n == 0 where n is the result of roundup_pow_of_two(...)
// Also detect !roundup_pow_of_two(x) and roundup_pow_of_two(x) == 0
void SAGenTestChecker::checkBranchCondition(const Stmt *Condition, CheckerContext &C) const {
  // Only warn on 32-bit unsigned long targets
  ASTContext &ACtx = C.getASTContext();
  if (ACtx.getTypeSize(ACtx.UnsignedLongTy) != 32)
    return;

  const Expr *CondE = dyn_cast_or_null<Expr>(Condition);
  if (!CondE)
    return;

  // Record the patch's guard relation first: an early-exit comparison that
  // bounds an input region to at most 1UL << 31 silences later
  // roundup_pow_of_two() binds on the same region.
  if (recordInputBound(CondE, C))
    return;

  const Expr *CheckedExpr = nullptr;
  if (!extractCheckedExpr(CondE, CheckedExpr, C))
    return;

  // Case 1: Direct call in the check (e.g., if (!roundup_pow_of_two(x)))
  if (const auto *CE = dyn_cast<CallExpr>(CheckedExpr->IgnoreParenImpCasts())) {
    if (isRoundupPow2Call(CE, C)) {
      reportIssue(Condition, CE, C);
      return;
    }
  }

  // Case 2: Variable previously assigned from roundup_pow_of_two(...)
  ProgramStateRef State = C.getState();
  const MemRegion *MR = getMemRegionFromExpr(CheckedExpr, C);
  if (!MR)
    return;
  MR = MR->getBaseRegion();
  if (!MR)
    return;

  if (const Stmt *const *OriginPtr = State->get<RoundupResMap>(MR)) {
    const Stmt *Origin = *OriginPtr;
    reportIssue(Condition, Origin, C);
    return;
  }
}

