// Locations that just received a fresh allocation result and have not yet been
// NULL-checked.  Each pending region is the destination of an allocator call;
// a branch condition that tests that exact region clears it (correct guard),
// while a test of a different region over the same base object leaves the
// allocation result unchecked (the patched bug: sve_state allocated, za_state
// tested).
REGISTER_SET_WITH_PROGRAMSTATE(PendingAllocCheck, const MemRegion *)

namespace {
class SAGenTestChecker : public Checker<check::Bind, check::BranchCondition> {
   mutable std::unique_ptr<BugType> BT;

   public:
      SAGenTestChecker() : BT(new BugType(this, "Wrong NULL check after allocation", "Logic error")) {}

      void checkBranchCondition(const Stmt *Condition, CheckerContext &C) const;
      // Record every location that receives a fresh allocation result so a
      // later NULL check can be compared against the allocation destination.
      void checkBind(SVal Loc, SVal Val, const Stmt *StoreE, CheckerContext &C) const;

   private:
      // Extract the pointer expression being NULL-checked in a condition.
      const Expr *extractNullCheckedPtr(const Expr *Cond, CheckerContext &C) const;
      // Determine if a CallExpr calls a known allocator (e.g., kzalloc, kmalloc, etc.).
      bool isKnownAllocatorCall(const CallExpr *CE, CheckerContext &C) const;
};

bool SAGenTestChecker::isKnownAllocatorCall(const CallExpr *CE, CheckerContext &C) const {
  if (!CE)
    return false;
  const Expr *CalleeE = CE->getCallee();
  if (!CalleeE)
    return false;

  // Use source-text-based name matching for robustness as suggested.
  static const char *Allocators[] = {
    "kzalloc", "kmalloc", "kcalloc", "kvzalloc", "vzalloc", "kvmalloc",
    "devm_kzalloc", "devm_kmalloc", "devm_kcalloc"
  };
  for (const char *Name : Allocators) {
    if (ExprHasName(CalleeE, Name, C))
      return true;
  }
  return false;
}

const Expr *SAGenTestChecker::extractNullCheckedPtr(const Expr *Cond, CheckerContext &C) const {
  if (!Cond)
    return nullptr;

  ASTContext &ACtx = C.getASTContext();
  const Expr *E = Cond->IgnoreParenCasts();

  if (const auto *UO = dyn_cast<UnaryOperator>(E)) {
    if (UO->getOpcode() == UO_LNot) {
      const Expr *SubE = UO->getSubExpr()->IgnoreParenCasts();
      if (SubE && SubE->getType()->isPointerType())
        return SubE;
    }
  } else if (const auto *BO = dyn_cast<BinaryOperator>(E)) {
    BinaryOperator::Opcode Op = BO->getOpcode();
    if (Op == BO_EQ) {
      const Expr *LHS = BO->getLHS()->IgnoreParenCasts();
      const Expr *RHS = BO->getRHS()->IgnoreParenCasts();

      bool LHSIsNull = LHS->isNullPointerConstant(ACtx, Expr::NPC_ValueDependentIsNull);
      bool RHSIsNull = RHS->isNullPointerConstant(ACtx, Expr::NPC_ValueDependentIsNull);

      if (LHSIsNull && RHS && RHS->getType()->isPointerType())
        return RHS;
      if (RHSIsNull && LHS && LHS->getType()->isPointerType())
        return LHS;
    }
  }
  return nullptr;
}

// Mechanism, store side: an assignment whose right-hand side is an allocator
// call stores a fresh allocation result into a pointer-typed location.  That
// location becomes "pending" until some branch condition NULL-checks it; any
// rebind replaces the previous content of the location first.
void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *StoreE, CheckerContext &C) const {
  const auto *BO = dyn_cast<BinaryOperator>(StoreE);
  if (!BO || BO->getOpcode() != BO_Assign)
    return;

  const Expr *LHS = BO->getLHS();
  const Expr *RHS = BO->getRHS();
  if (!LHS || !RHS)
    return;

  const MemRegion *Dest = Loc.getAsRegion();
  if (!Dest || !LHS->getType()->isPointerType())
    return;

  ProgramStateRef State = C.getState()->remove<PendingAllocCheck>(Dest);
  if (isKnownAllocatorCall(dyn_cast<CallExpr>(RHS->IgnoreParenCasts()), C))
    State = State->add<PendingAllocCheck>(Dest);
  if (State != C.getState())
    C.addTransition(State);
}

// Mechanism, check side: a NULL test of a location guards only that location.
// If a fresh allocation is still pending in a *different* location over the
// same base object, this branch cannot observe that allocation's failure
// (patch: sve_state was allocated, the condition tested za_state).  Testing
// the pending location itself is the correct guard and clears the pending set
// on both branch outcomes.
void SAGenTestChecker::checkBranchCondition(const Stmt *Condition, CheckerContext &C) const {
  if (!Condition)
    return;

  const auto *CondE = dyn_cast<Expr>(Condition);
  if (!CondE)
    return;

  const Expr *CheckedPtrExpr = extractNullCheckedPtr(CondE, C);
  if (!CheckedPtrExpr || !CheckedPtrExpr->getType()->isPointerType())
    return;

  ProgramStateRef State = C.getState();
  const MemRegion *ChkRegion =
      State->getSVal(CheckedPtrExpr, C.getLocationContext()).getAsRegion();
  if (!ChkRegion)
    return;

  ProgramStateRef Next = State->remove<PendingAllocCheck>(ChkRegion);

  llvm::SmallVector<const MemRegion *, 4> Unchecked;
  for (const MemRegion *AllocRegion : State->get<PendingAllocCheck>()) {
    if (AllocRegion != ChkRegion &&
        AllocRegion->getBaseRegion() == ChkRegion->getBaseRegion())
      Unchecked.push_back(AllocRegion);
  }

  if (Unchecked.empty()) {
    if (Next != State)
      C.addTransition(Next);
    return;
  }

  for (const MemRegion *AllocRegion : Unchecked)
    Next = Next->remove<PendingAllocCheck>(AllocRegion);

  ExplodedNode *N = C.generateNonFatalErrorNode(Next);
  if (!N)
    return;

  for (const MemRegion *AllocRegion : Unchecked) {
    auto R = std::make_unique<PathSensitiveBugReport>(
        *BT, "NULL check tests a different location of the same object as the "
             "freshly allocated one", N);
    R->addRange(CondE->getSourceRange());
    R->markInteresting(AllocRegion);
    C.emitReport(std::move(R));
  }
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
      "Detects checking a different pointer than the one just allocated (wrong NULL check)",
      "");
}

