      if (const auto *IL = dyn_cast<IntegerLiteral>(L)) {
        if (IL->getValue() == 1 && L->getType()->isUnsignedIntegerType() &&
            !isa<IntegerLiteral>(R)) {
          ShiftOut = BO;
          return true;
        }
      }
    }
  }

  for (const Stmt *Ch : S->children())
    if (findRoundingShift(Ch, ShiftOut))
      return true;

  return false;
}

// Capacity of the shifted operand. unsigned long may be as narrow as 32 bits
// on supported targets, so a UL-based shift is only guaranteed to hold 32
// bits; unsigned long long is exactly 64 bits.
unsigned SAGenTestChecker::shiftOperandWidth(QualType T, CheckerContext &C) {
  if (!T->isUnsignedIntegerType())
    return 0;
  if (T->isSpecificBuiltinType(BuiltinType::ULongLong))
    return 64;
  unsigned Actual = C.getASTContext().getTypeSize(T);
  return Actual > 32 ? 32 : Actual;
}

// Recover the expression whose value is being rounded from the shift amount:
// "ilog2(x - 1) + 1" -> "x".
const Expr *SAGenTestChecker::extractRoundingInput(const Expr *ShiftRHS) {
  auto IsOne = [](const Expr *E) {
    if (const auto *IL = dyn_cast<IntegerLiteral>(E->IgnoreParenImpCasts()))
      return IL->getValue() == 1;
    return false;
  };

  const Expr *E = ShiftRHS->IgnoreParenImpCasts();
  // strip the "+ 1" of the roundup formula
  if (const auto *BO = dyn_cast<BinaryOperator>(E)) {
    if (BO->getOpcode() == BO_Add) {
      if (IsOne(BO->getRHS()))
        E = BO->getLHS()->IgnoreParenImpCasts();
      else if (IsOne(BO->getLHS()))
        E = BO->getRHS()->IgnoreParenImpCasts();
    }
  }
  // strip the logarithm-style call
  if (const CallExpr *CE = findSpecificTypeInChildren<CallExpr>(E))
    E = CE->getArg(0)->IgnoreParenImpCasts();
  // strip the "- 1" before taking the logarithm
  if (const auto *BO = dyn_cast<BinaryOperator>(E)) {
    if (BO->getOpcode() == BO_Sub && IsOne(BO->getRHS()))
      E = BO->getLHS()->IgnoreParenImpCasts();
  }
  return E;
}

// The patch's capacity relation: the rounding input must stay within
// 2^(Width-1) for the shift to fit its operand. True when the current path
// already enforces that relation.
bool SAGenTestChecker::inputBounded(ProgramStateRef State, CheckerContext &C,
                                    SymbolRef Input, unsigned Width) {
  if (!Input || Width == 0 || Width > 64)
    return false;

  ASTContext &ACtx = C.getASTContext();
  QualType T = Input->getType(ACtx);
  if (!T->isIntegerType())
    return false;
  unsigned InBits = ACtx.getIntWidth(T);
  if (InBits < Width)
    return true; // the input type cannot reach the overflow threshold

  llvm::APInt V(InBits, 1);
  V <<= (Width - 1);
  llvm::APSInt Limit(V, T->isUnsignedIntegerType());

  SValBuilder &SVB = C.getSValBuilder();
  SVal Le = SVB.evalBinOp(State, BO_LE, nonloc::SymbolVal(Input),
                          SVB.makeIntVal(Limit), SVB.getConditionType());
  if (auto LeD = Le.getAs<DefinedSVal>()) {
    // Bounded only when "input > limit" is impossible on this path.
    return State->assume(*LeD, false) == nullptr;
  }
  return false;
}

// Report a concise warning
void SAGenTestChecker::reportIssue(const Stmt *CondSite, const Stmt *OriginCE, CheckerContext &C) const {
  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(
      *BT,
      "Unreliable overflow check after roundup_pow_of_two()",
      N);

  if (CondSite)
    R->addRange(CondSite->getSourceRange());

  if (OriginCE) {
    PathDiagnosticLocation Loc =
        PathDiagnosticLocation::createBegin(OriginCE, C.getSourceManager(), C.getLocationContext());
    R->addNote("Value comes from roundup_pow_of_two() here", Loc);
  }

  if (CondSite) {
    PathDiagnosticLocation Loc2 =
        PathDiagnosticLocation::createBegin(CondSite, C.getSourceManager(), C.getLocationContext());
    R->addNote("roundup_pow_of_two() may overflow (UB) on 32-bit; check the input before rounding (e.g., x > 1UL << 31).", Loc2);
  }

  C.emitReport(std::move(R));
}

// Track binds: mark variables assigned from roundup_pow_of_two(...); clear otherwise
void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const {
  const MemRegion *LReg = Loc.getAsRegion();
  if (!LReg)
    return;
  LReg = LReg->getBaseRegion();
  if (!LReg)
    return;

  ProgramStateRef State = C.getState();

  // Recognize a rounding computation structurally: the shift that the
  // roundup_pow_of_two() macro lowers to (an unsigned literal 1 shifted by
  // an input-derived amount), or a direct call to a rounding helper.
  const BinaryOperator *Shift = nullptr;
  const Stmt *Origin = nullptr;
  const Expr *InputExpr = nullptr;
  unsigned Width = 0;

  if (findRoundingShift(S, Shift)) {
    Origin = Shift;
    Width = shiftOperandWidth(Shift->getLHS()->IgnoreParenImpCasts()->getType(), C);
    InputExpr = extractRoundingInput(Shift->getRHS());
  } else if (const CallExpr *CE = findSpecificTypeInChildren<CallExpr>(S)) {
    if (isRoundupPow2Call(CE, C)) {
      Origin = CE;
      Width = shiftOperandWidth(CE->getType(), C);
      if (CE->getNumArgs() > 0)
        InputExpr = CE->getArg(0);
    }
  }

  if (Origin) {
    SymbolRef Input = nullptr;
    if (InputExpr) {
      if (const MemRegion *IR = getMemRegionFromExpr(InputExpr, C))
        Input = State->getSVal(loc::MemRegionVal(IR)).getAsSymbol();
    }
    State = State->set<RoundupResMap>(LReg, RoundupShiftInfo{Origin, Input, Width});
  } else {
    State = State->remove<RoundupResMap>(LReg);
  }

  C.addTransition(State);
}

// Detect post-hoc zero checks on a rounding result: once the input exceeds
// the shift operand's capacity, the shift has already overflowed (UB), so
// testing the rounded value for zero cannot recover. Stay silent when the
// path already bounds the input (the relation the patch's guard adds).
void SAGenTestChecker::checkBranchCondition(const Stmt *Condition, CheckerContext &C) const {
  const Expr *CondE = dyn_cast_or_null<Expr>(Condition);
  if (!CondE)
    return;

  const Expr *CheckedExpr = nullptr;
  if (!extractCheckedExpr(CondE, CheckedExpr, C))
    return;

  ProgramStateRef State = C.getState();

  // Case 1: the checked expression is itself a rounding computation
  // (e.g., if (!roundup_pow_of_two(x)) after macro expansion)
  const BinaryOperator *Shift = nullptr;
  if (findRoundingShift(CheckedExpr, Shift)) {
    unsigned W = shiftOperandWidth(Shift->getLHS()->IgnoreParenImpCasts()->getType(), C);
    SymbolRef Input = nullptr;
    if (const Expr *In = extractRoundingInput(Shift->getRHS())) {
      if (const MemRegion *IR = getMemRegionFromExpr(In, C))
        Input = State->getSVal(loc::MemRegionVal(IR)).getAsSymbol();
    }
    if (!inputBounded(State, C, Input, W)) {
      reportIssue(Condition, Shift, C);
      return;
    }
  }

  // Case 2: Variable previously assigned from a rounding computation
  const MemRegion *MR = getMemRegionFromExpr(CheckedExpr, C);
  if (!MR)
    return;
  MR = MR->getBaseRegion();
  if (!MR)
    return;

  if (const RoundupShiftInfo *Info = State->get<RoundupResMap>(MR)) {
    // The capacity relation the patch's guard establishes already holds.
    if (inputBounded(State, C, Info->Input, Info->Width))
      return;
    reportIssue(Condition, Info->Origin, C);
    return;
  }
}

