#include "clang/AST/Attr.h"
#include "llvm/ADT/ImmutableMap.h"

using namespace clang;
using namespace ento;
using namespace taint;

// Program state: Track auto-cleanup pointer locals (kfree) and whether initialized.
REGISTER_MAP_WITH_PROGRAMSTATE(TrackedAutoCleanup, const VarDecl *, bool)

namespace {

class SAGenTestChecker : public Checker<
                             check::PostStmt<DeclStmt>,
                             check::Bind,
                             check::PostCall,
                             check::PreStmt<ReturnStmt>,
                             check::EndFunction> {
   mutable std::unique_ptr<BugType> BT;

   public:
      SAGenTestChecker() : BT(new BugType(this, "Auto-cleanup pointer may be freed uninitialized", "Memory Management")) {}

      void checkPostStmt(const DeclStmt *DS, CheckerContext &C) const;
      void checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const;
      void checkPostCall(const CallEvent &Call, CheckerContext &C) const;
      void checkPreStmt(const ReturnStmt *RS, CheckerContext &C) const;
      void checkEndFunction(const ReturnStmt *RS, CheckerContext &C) const;

   private:
      static bool hasKfreeCleanup(const VarDecl *VD);
      void reportUninitializedAtExit(const Stmt *Trigger, CheckerContext &C) const;
};

static PathDiagnosticLocation getDeclLoc(const VarDecl *VD, CheckerContext &C) {
  return PathDiagnosticLocation::createBegin(VD, C.getSourceManager());
}

static bool isDirectKfree(const FunctionDecl *FD) {
  if (!FD)
    return false;
  if (const IdentifierInfo *II = FD->getIdentifier())
    return II->getName() == "kfree";
  return false;
}

// Detects cleanup callbacks that forward their parameter to kfree, e.g. the
// __free_kfree static inline produced by the kernel's __free(kfree) macro.
// This is a callback/argument relation, so a consistent wrapper rename keeps
// the deallocation contract recognized.
class KfreeForwardVisitor : public RecursiveASTVisitor<KfreeForwardVisitor> {
  const ParmVarDecl *Param;
  bool Found = false;

 public:
  explicit KfreeForwardVisitor(const ParmVarDecl *P) : Param(P) {}

  bool VisitCallExpr(CallExpr *CE) {
    const FunctionDecl *Callee = CE->getDirectCallee();
    if (!Callee || !isDirectKfree(Callee))
      return true;
    for (Expr *Arg : CE->arguments()) {
      if (!Arg)
        continue;
      if (const DeclRefExpr *DRE =
              dyn_cast<DeclRefExpr>(Arg->IgnoreParenImpCasts())) {
        if (DRE->getDecl() == Param) {
          Found = true;
          return false;
        }
      }
    }
    return true;
  }

  bool found() const { return Found; }
};

static bool cleanupFreesMemory(const FunctionDecl *FD) {
  if (isDirectKfree(FD))
    return true;
  // Generated cleanup wrappers (e.g. __free_kfree) pass their parameter
  // straight to kfree; verify that relation in the wrapper body so the
  // deallocation semantics, not the wrapper spelling, drives tracking.
  if (!FD || !FD->hasBody() || FD->param_size() == 0)
    return false;
  KfreeForwardVisitor V(FD->getParamDecl(0));
  V.TraverseStmt(FD->getBody());
  return V.found();
}

bool SAGenTestChecker::hasKfreeCleanup(const VarDecl *VD) {
  if (!VD)
    return false;
  const CleanupAttr *CA = VD->getAttr<CleanupAttr>();
  if (!CA)
    return false;

  // Track deallocation cleanup callbacks: kfree itself, or a wrapper whose
  // body forwards its parameter to kfree (compiler lowering of __free(kfree)).
  // If the callback cannot be resolved to a freeing contract, do not track.
  return cleanupFreesMemory(CA->getFunctionDecl());
}

void SAGenTestChecker::checkPostStmt(const DeclStmt *DS, CheckerContext &C) const {
  ProgramStateRef State = C.getState();

  for (const Decl *D : DS->decls()) {
    const auto *VD = dyn_cast<VarDecl>(D);
    if (!VD)
      continue;

    // Only track automatic local pointers with cleanup(kfree) and no initializer.
    if (!VD->hasLocalStorage())
      continue;

    if (VD->getStorageDuration() != SD_Automatic)
      continue;

    QualType QT = VD->getType();
    if (QT.isNull() || !QT->isPointerType())
      continue;

    if (!hasKfreeCleanup(VD))
      continue;

    // If it has an initializer (even non-NULL), treat as initialized; skip tracking.
    if (VD->hasInit())
      continue;

    // Start tracking as "not initialized" (false).
    State = State->set<TrackedAutoCleanup>(VD, false);
  }

  if (State != C.getState())
    C.addTransition(State);
}

void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  const MemRegion *MR = Loc.getAsRegion();
  if (!MR)
    return;

  if (const auto *VR = dyn_cast<VarRegion>(MR->getBaseRegion())) {
    const VarDecl *VD = VR->getDecl();
    if (!VD)
      return;

    const bool *Tracked = State->get<TrackedAutoCleanup>(VD);
    if (Tracked) {
      // Any assignment counts as initialization.
      State = State->set<TrackedAutoCleanup>(VD, true);
      C.addTransition(State);
    }
  }
}

void SAGenTestChecker::checkPostCall(const CallEvent &Call, CheckerContext &C) const {
  ProgramStateRef State = C.getState();

  // If an argument is &var where var is tracked, conservatively treat it as initialized.
  for (unsigned i = 0, e = Call.getNumArgs(); i < e; ++i) {
    const Expr *ArgE = Call.getArgExpr(i);
    if (!ArgE)
      continue;

    const Expr *E = ArgE->IgnoreParenCasts();
    const UnaryOperator *UO = dyn_cast<UnaryOperator>(E);
    if (!UO || UO->getOpcode() != UO_AddrOf)
      continue;

    const Expr *Sub = UO->getSubExpr();
    if (!Sub)
      continue;
    Sub = Sub->IgnoreParenCasts();

    if (const auto *DRE = dyn_cast<DeclRefExpr>(Sub)) {
      const auto *VD = dyn_cast<VarDecl>(DRE->getDecl());
      if (!VD)
        continue;

      const bool *Tracked = State->get<TrackedAutoCleanup>(VD);
      if (Tracked && *Tracked == false) {
        State = State->set<TrackedAutoCleanup>(VD, true);
      }
    }
  }

  if (State != C.getState())
    C.addTransition(State);
}

void SAGenTestChecker::reportUninitializedAtExit(const Stmt *Trigger, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  auto Map = State->get<TrackedAutoCleanup>();

  for (auto I = Map.begin(), E = Map.end(); I != E; ++I) {
    const VarDecl *VD = I->first;
