// Track released-but-not-cleared struct fields.
REGISTER_SET_WITH_PROGRAMSTATE(ReleasedFieldSet, const MemRegion*)

// Record where a field was released: the release statement (for
// diagnostics), the frame that performed the release, and whether that
// frame issued an owner-transfer call for the whole object (as opposed to
// a helper tearing down one field inside an inlined release helper).
struct ReleaseInfo {
  const Stmt *Site;
  const LocationContext *Frame;
  bool FromOwnerCall;

  bool operator==(const ReleaseInfo &O) const {
    return Site == O.Site && Frame == O.Frame &&
           FromOwnerCall == O.FromOwnerCall;
  }
};

REGISTER_MAP_WITH_PROGRAMSTATE(ReleaseSiteMap, const MemRegion*, ReleaseInfo)

namespace {

struct OwnerReleaseSpec {
  const char *FuncName;
  unsigned ObjParamIndex;
  const char *FieldName;
};

// Known direct release functions: arg0 is the released pointer.
static const char *DirectReleaseFns[] = {
  "fput",
  "filp_close",
  "blkdev_put"
};

// Known owner-release: a function that releases a specific field of the object passed.
static const OwnerReleaseSpec OwnerReleases[] = {
  // btrfs_close_bdev(device) releases device->bdev_file
  { "btrfs_close_bdev", 0, "bdev_file" }
};

// Jointly-owned validity pairs on the owning record: the released field and
// its guard sibling are only set and cleared together, so a live release of
// the field implies the sibling holds the same ownership at that point.
struct FieldCouplingSpec {
  const char *ReleasedField;
  const char *GuardField;
};

static const FieldCouplingSpec FieldCouplings[] = {
